criteria.query:
let expected = union (datatable(Computer:string)["WS01", "WS02"]), (Heartbeat | where TimeGenerated > ago(2d) | distinct Computer) | extend Computer = toupper(tostring(split(Computer, '.')[0])) | distinct Computer;
let seen = Heartbeat | where TimeGenerated > ago(24h) | extend Computer = toupper(tostring(split(Computer, '.')[0])) | distinct Computer;
expected | join kind=leftanti seen on Computer | extend Problem = strcat(Computer, ' has sent no telemetry for over 24 hours. Expected if it is switched off; otherwise investigate.')
